 const pending=autoGate.pending;
 if(pending){const discovery=pending.action.discovery;if(discovery&&(walker.currentRoomId!==discovery.roomId||distance(walker.position,discovery.discovery.approachMeters)>1.5)){autoGate.cancel();return;}if(pending.action.slot&&!session.near(pending.action.slot,pose())){const a=markerActors.find(a=>a.slot?.id===pending.action.slot.id);if(a)a.model.position.fromArray(a.slot.displayMeters||a.slot.approachMeters);autoGate.cancel();return;}const elapsed=gameTime-pending.start,action=pending.action,actor=markerActors.find(a=>a.slot?.id===action.slot?.id),model=actor?.model||action.spirit?.g;
  if(model&&(action.slot?.role==='ghost'||action.spirit)){const base=action.slot?.approachMeters||action.spirit.g.position.toArray(),p=walker.position,t=Math.min(1,elapsed/1500),a=t*Math.PI*2;const candidate=[p[0]+Math.sin(a)*.8,p[1],p[2]+Math.cos(a)*.8];const room=house.rooms.find(r=>r.id===walker.currentRoomId);if(!reduced&&mode==='house'&&room&&roomContains(room,candidate,.3)&&!blockedByFurniture(house,room.floor,candidate[0],candidate[2],candidate[1]))model.position.set(candidate[0],base[1]+.1,candidate[2]);}
  if(actor&&['founder','seer'].includes(action.slot?.role)){actor.model.rotation.z=reduced?0:Math.sin(elapsed*.018)*.035;actor.model.traverse(o=>{if(o.userData.portraitHalo)o.material.opacity=.20+Math.sin(elapsed*.005)*.12;});}if(action.portrait){action.portrait.mesh.material.emissiveIntensity=.7;action.portrait.mount.rotation.z=reduced?0:Math.sin(elapsed*.018)*.06;}
  if(elapsed>=(action.instant?100:reduced?300:1600)){const next=autoGate.finish();if(model&&(action.slot?.role==='ghost'||action.spirit)){const p=walker.position,room=house.rooms.find(r=>r.id===walker.currentRoomId);for(const d of [.85,.6,.4]){const q=[p[0]-Math.sin(walker.yaw)*d,p[1],p[2]-Math.cos(walker.yaw)*d];if(mode==='house'&&room&&roomContains(room,q,.25)&&!blockedByFurniture(house,room.floor,q[0],q[2],q[1])){model.position.fromArray(q);break;}}}else if(actor)actor.model.position.fromArray(actor.slot.displayMeters||actor.slot.approachMeters);Promise.resolve().then(()=>next.run()).then(()=>checkpoint()).catch(e=>toast(e.message));}return;
 }
 const action=nearestAction();if(!action?.automatic)return;
 // Room and height checks belong to each action; a ray prevents speaking through walls.
 let target=action.slot?.approachMeters||action.discovery?.discovery.approachMeters||action.portrait?.anchor||action.spirit?.g.position.toArray();let visible=true;
 if(target){const from=new THREE.Vector3(...walker.position);from.y+=1.4;const to=new THREE.Vector3(...target);to.y+=1.4;const delta=to.sub(from),distance=delta.length();if(distance>.12){const ray=new THREE.Raycaster(from,delta.normalize(),.10,Math.max(.1,distance-.18));visible=!ray.intersectObjects(mode==='house'?activeGroup?.userData?.cameraOccluders||[]:[],false).length;}}
