function drawMap(floor){const canvas=$('mapCanvas'),ctx=canvas.getContext('2d');ctx.fillStyle='#0d1119';ctx.fillRect(0,0,canvas.width,canvas.height);let rooms=house.rooms.filter(r=>r.floor===floor&&(session.mapUnlocked||session.state.visited.includes(r.id)));if(!rooms.length){ctx.fillStyle='#d9c8ad';ctx.font='20px Georgia';ctx.fillText('No rooms discovered on this floor.',35,65);return;}const bs=rooms.map(r=>r.boundsFeet),minX=Math.min(...bs.map(b=>+b.x)),minZ=Math.min(...bs.map(b=>+b.y)),maxX=Math.max(...bs.map(b=>+b.x+ +b.l)),maxZ=Math.max(...bs.map(b=>+b.y+ +b.w)),scale=Math.min(650/(maxX-minX||1),390/(maxZ-minZ||1));for(const r of rooms){const b=r.boundsFeet,x=50+(+b.x-minX)*scale,z=50+(+b.y-minZ)*scale;ctx.fillStyle=r.id===currentRoom?.id?'#5e746f':'#2c303e';ctx.fillRect(x,z,+b.l*scale,+b.w*scale);ctx.strokeStyle='#b09c78';ctx.strokeRect(x,z,+b.l*scale,+b.w*scale);ctx.fillStyle='#eee2cb';ctx.font='11px system-ui';ctx.fillText((r.name||r.id).slice(0,22),x+4,z+15);}ctx.fillStyle='#bcd2c4';ctx.font='14px system-ui';ctx.fillText(session.mapUnlocked?'THE CARTOGRAPHER’S ESTATE MAP':'YOUR DISCOVERIES',40,28);}

function ENDINGS_TEXT(choice){return STREET_ECHOES[choice]||'The house carries the memory of your choice.';}
const STREET_ECHOES={release:'A small light waits patiently at the gate.',claim:'The watching light follows you beyond the windows.',sing:'Three rings hum above the mailbox.',silence:'The rings hold a beautiful silence.',home:'A warm light has someone to come home to.',road:'The little light is ready for the road.',tomorrow:'A clock-shaped trace points toward morning.',preserve:'One perfect minute is held in brass.',invite:'Living leaves curl toward the extra place at the table.',banish:'An empty invitation waits beside the gate.',free:'The broker’s mark no longer has a chain.',deal:'The corrected bargain is remembered in green.',escape:'A sliver of stolen amber shines above the post.',name:'A remembered name glows where the Collector cannot reach.',sky:'Moonlit leaves reach toward the sky you released.',seed:'Something impossible is growing beside the mailbox.'};
function applyStreetFate(){if(playMode==='midway')return;if(playMode==='halloween'||mode!=='street'&&activeGroup!==street?.root)return;const fate=night.data.streetFate;if(fate==='dawn'){scene.background.set(0x433347);scene.fog.color.set(0x79616b);}else if(fate==='night'){scene.background.set(0x1e1839);scene.fog.color.set(0x302443);}}
function streetMemoryChallengeList(witness){return streetLedger(night).split('\n').filter(line=>line.startsWith('AWAKE · ')||line.startsWith('WAITING · ')).map(line=>line.startsWith('AWAKE · ')?'✓ COMPLETED — '+line.slice(8):'○ NOT COMPLETED — '+line.slice(10)).join('\n');}
function openNinthDoor(){const witness=streetMemory?.witness;if(!witness)return;if(witness.fate)return showModal(STREET_FATES[witness.fate].title,STREET_FATES[witness.fate].text+'\n\nYour mansions remain open. New hauntings can still be awakened.');const choices=witness.ready?[{label:'Let Black Hollow see morning',action:()=>chooseStreetFate('dawn')},{label:'Keep the night, open every door',action:()=>chooseStreetFate('night')}]:[{label:'Return to the Haunted Houses',action:()=>{streetScene();toast('Walk to a porch and tap Yes to enter a house.',5500);}},{label:'How to Find a House',action:()=>map()}];showModal(witness.ready?'The Ninth Door · Finale':'The Ninth Door — Not Yet Unlocked',witness.ready?'Eight different hauntings. Eight endings remembered. The door opens onto a sky that has never existed. What will you give the street?':'EIGHT SEALS. EIGHT DIFFERENT HAUNTINGS. ONE FINAL MYSTERY.\n\nYou have discovered the Ninth Door, but you have not unlocked it yet.\n\nTO UNLOCK THIS DOOR, COMPLETE THE FOLLOWING HAUNTING CHALLENGES:\n\n'+streetMemoryChallengeList(witness)+'\n\nYOUR PROGRESS: '+witness.seals.length+' OF 8 SEALS EARNED\n\nExplore a house, complete its haunting story, and earn its seal. Each different type of haunting counts once; either ending qualifies. You may revisit houses for different challenges.\n\nThe Ninth Door remembers what you accomplish. Return when all eight seals are yours.',{choices});}
function chooseStreetFate(fate){if(!night.resolveStreet(fate))return;streetMemory?.resolve(fate);applyStreetFate();audio.cue('complete');showModal(STREET_FATES[fate].title,STREET_FATES[fate].text+(night.persisted?'\n\nThis choice is remembered on this device.':'\n\nDevice storage is unavailable; this choice lasts for this session.')+' The houses and their hauntings remain open.');}

function streetGuide(){return 'THE CROOKED HAT VILLAGE\nRing the Crooked Hat clock to call the roaming neighbours home. Its other calls help you find unfinished stalls.\n\nLook for the roaming neighbours along each street: greet Moth the ghost cat, watch Hemlock fetch a thrown bone, or invite a nearby witch to dance. Each keeps a different route and schedule. The town bell calls them home. These encounters are free to replay in both modes.\n\nAt the intersection: brew at Nettle’s stall, park Violet, and play Rose → Moss → Plum. Each earns a saved passport stamp; in Trick or Treat each earns one bonus sweet per round.\nPassport: '+villagePassport.badges.length+'/3 · '+(villagePassport.badges.length===3?'Neighbour of the Crooked Hat':'Curious visitor')+'\n\nHOW TO PLAY BLACK HOLLOW\n1. Walk along the street toward a house.\n2. Approach its porch and tap YES to enter (or press E).\n3. Explore, follow the house objective, and finish its haunting.\n4. Each different haunting family earns one seal.\n5. Return to the Ninth Door only after collecting all eight seals.\n\nHOUSES ON THE STREETS\n\n'+street.lanes.map(l=>l.name+' · '+l.houses.length+' houses\n'+(l.houses.map(h=>'  '+h.houseNumber+' · '+h.name).join('\n')||'  Houses can be added here.')).join('\n\n')+'\n\nAll four streets meet at the town intersection and end in roundabouts.\n\n'+streetLedger(night,catalog.list());}
function map(){if(midwayRide)return midwayRide.showGuide();if(playMode==='midway'&&mode==='street')return showModal('The Haunted Midway','Approach a mansion porch and board its phantom carriage. The haunted elevator carries it between rooms and floors. Pause, adjust speed, look around or return whenever you like.');if(mode==='floor13'&&session?.phoenix)return showHerbarium();if(session?.phoenix)return hauntingJournal();if(mode==='street')return showModal('Black Hollow · streets',streetGuide(),{choices:[{label:'Open my village passport',action:showVillagePassport}]});if(playMode==='halloween')return showModal('Halloween street',catalog.list().map(h=>h.name).join('\n')+'\n\nEvery doorstep can change on every visit. Step away, then return.');if(!house)return showModal('Black Hollow',catalog.list().map(h=>h.name).join('\n'));const floor=Math.max(0,currentRoom?.floor||0),choices=house.manifest.floors.map((f,i)=>({f,i})).filter(({i})=>session.floor13Unlocked||!house.access.stops.some(s=>s.floor===i&&s.requiresUnlock)).map(({f,i})=>({label:f.name||'Floor '+(i+1),action:()=>{showMap(i);}}));if(session.state.memories.length)choices.push({label:'Read the memory journal',action:()=>showModal('The memory journal',session.story.memories.slice(0,session.state.memories.length).map((text,i)=>(i+1)+'. '+text).join('\n\n'))});function showMap(i){showModal(session.mapUnlocked?'The estate map':'Your discoveries',session.mapUnlocked?'The Founder’s reward reveals the whole house.':'Explore to record rooms. Resolve Floor 13 to unlock the complete estate map.',{map:true,choices});drawMap(i);}showMap(floor);}
function tick(time){requestAnimationFrame(tick);const trickElapsed=trickClock?Math.max(0,(time-trickClock)/1000):0;trickClock=time;audio.scoreFrame(scoreState(session,{mode,paused:!playing||dialog||busy||document.hidden}));audio.tick(time);if(storyBeatUntil&&time>storyBeatUntil)dismissStoryBeat();if(document.hidden||!renderer)return;if(time-lastFrame<1000/30)return;const activeDt=Math.min(1,(time-lastFrame)/1000||.016),dt=Math.min(.05,activeDt);lastFrame=time;if(midwayRide){if(playing&&!dialog&&!busy){gameTime+=dt*1000;midwayRide.update(dt,time);needsRender=true;}if(needsRender){renderer.render(scene,camera);needsRender=false;}return;}if(endingPerformance&&playing&&(!dialog||$('modal').classList.contains('ending-view'))){endingPerformance.tick(dt);needsRender=true;}if(playing&&!dialog&&!busy){needsRender=true;gameTime+=dt*1000;if(narrationUntil&&gameTime>narrationUntil)finishNarration();if(mode==='house')updateStairWindow();walker.update(time);magicRealm?.configure(mode,house,currentRoom,session);magicRealm?.tick(dt,walker.position);tickHaunting(activeDt);if(playMode==='halloween'&&mode==='street')updateTrickOrTreat(trickElapsed,dt);updateAutomaticEncounters();if(mode==='hall'&&walker.position[1]<.35&&Math.abs(walker.position[0])<.67&&walker.position[2]>14.8){void transition(enterMainHouse);}else if(mode==='hall'&&walker.position[1]<.35&&Math.abs(walker.position[0])<.67&&walker.position[2]<-14.8){void transition(groundsScene);}if(['hall','house','floor13'].includes(mode)&&!busy){const stop=nearStop(),door=markers.children.find(m=>m.userData.stopId===stop?.id);if(stop&&!hallCabinOccupied&&(!door||door.userData.open>=.98)){hallCabinOccupied=true;void board(stop);}else if(!stop)hallCabinOccupied=false;}if(mode==='cabin'&&liftDoors){liftClosing=Math.min(1,liftClosing+dt);for(const door of liftDoors.children)door.position.x=door.userData.side*(.55+(1-liftClosing)*1.1);if(liftClosing===1){audio.cue('lift');elevatorPanel();}}atmosphere.tick(gameTime,dt,walker.position);if(mode==='street'){street.tick(gameTime,walker.position,walker.yaw);streetMemory?.tick(gameTime,dt);}if(mode==='hall')activeGroup?.userData.household?.tick(gameTime,dt,walker.position);if(mode==='floor13')activeGroup?.userData.nocturne?.tick(gameTime,walker.position);if(mode==='hall')activeGroup?.userData.grandHall?.userData.tick?.(gameTime);if(mode==='hall')activeGroup?.userData.hallOrgan?.tick(gameTime,dt,walker.position,audio.musicFrame());for(const entrance of markers.children)entrance.userData.updateLift?.(dt,walker.position,{forceOpen:mode==='hall'&&activeGroup?.userData.hallOrgan?.needsElevator});entryBlend=Math.min(1,entryBlend+dt/3);renderer.toneMappingExposure=['house','hall','floor13'].includes(mode)?1.48-entryBlend*.12:1.58;const walkingPosition=walker.position;if(lastStepPosition){stepDistance+=distance(walkingPosition,lastStepPosition);if(stepDistance>.70&&time-lastStepTime>220){audio.effect('step',{surface:footstepSurface(mode==='house'?house.rooms.find(r=>r.id===walker.currentRoomId):currentRoom,mode)});stepDistance=0;lastStepTime=time;}}lastStepPosition=[...walkingPosition];if(['house','hall','floor13'].includes(mode))haunting.tick(gameTime,walkingPosition,walker.currentRoomId,{yaw:walker.yaw,canSeeSite:site=>scareSiteVisible(THREE,site,camera,activeGroup?[activeGroup]:[]),enabled:mode==='house'&&!magicRealm?.active&&!narrationUntil&&!autoGate?.pending&&!storyBeatUntil&&!session?.holding&&!(session?.phoenix&&session.type==='vigil'&&session.watch().watching)});if(mode==='house'&&!session.phoenix&&!autoGate?.pending&&!narrationUntil&&!haunting.scareTheatre?.director.active){const event=director.tick(dt,{roomId:walker.currentRoomId,stage:session.state.stage});if(event){haunting.event(event);audio.effect(event.kind,{pan:Math.sin(gameTime)*.65});toast(event.text,4500);checkpoint();}}if(collectorPresence){const visible=session.state.alarm>=30&&walker.currentRoomId===session.stations[3].roomId;collectorPresence.root.visible=visible;collectorPresence.update(session.state.alarm,gameTime,{reducedMotion:reduced});collectorPresence.root.rotation.y=Math.atan2(walker.position[0]-collectorPresence.root.position.x,walker.position[2]-collectorPresence.root.position.z);if(session.state.alarm>=30&&gameTime-lastCollectorStep>Math.max(650,2500-session.state.alarm*17)){lastCollectorStep=gameTime;audio.effect('step',{surface:'stone',pan:.5});}}for(const actor of markerActors){if(session.phoenix){actor.model.userData.tick?.(reduced?0:gameTime);const since=gameTime-(actor.model.userData.respondAt??-9999);if(!reduced&&since>=0&&since<650)actor.model.scale.setScalar(actor.model.userData.baseScale*(1+Math.sin(since/650*Math.PI)*.12));else actor.model.scale.setScalar(actor.model.userData.baseScale||1);if(actor.slot?.index===0&&session.type==='escort'&&session.state.escortStarted){actor.model.visible=false;}}actor.model.userData.fabric?.userData.animateFabric(gameTime);actor.model.userData.wraithMotion?.update(gameTime);actor.model.position.y=actor.base+(reduced?0:Math.sin(gameTime*.0018)*.045);if(actor.slot?.rotationY==null)actor.model.rotation.y=Math.atan2(camera.position.x-actor.model.position.x,camera.position.z-actor.model.position.z);}if(time-lastHUD>180){lastHUD=time;updateHUD();if(mode==='house'){const p=walker.position;atmosphere.setLights(selectHouseLights(house,{roomId:walker.currentRoomId,floor:currentRoom.floor,position:p,quality:lightingQuality}));}if(mode==='hall')atmosphere.setLights(nearbyHallLights([{position:[-11.4,1,-11.5],color:0xff9a4d,intensity:7,distance:5},...(activeGroup?.userData.hallLightSpecs||[])],walker.position));if(mode==='street')refreshPreviews();}if(time-lastSave>6000){checkpoint();lastSave=time;}}if(time>toastUntil)$('toast').style.display='none';if(needsRender){renderer.render(scene,camera);needsRender=false;}}

function showHauntingIntro(){
 session.state.encounters['phoenix:intro']=true;checkpoint();
 showModal(session.definition.title,HOUSE_VOICES[session.type].opening+'\n\nGrand Main Hall: visit the household, or enter the main house beneath the stairs.\n\nYOUR FIRST MOVE\n'+FIRST_MOVES[session.type]+'\n\n'+lanternGuide(session,pose()).location+'\n\nNo timer or dread builds until your first interaction. Full rules stay in the field journal.',{choices:[{label:'Explore the main hall',action:()=>resume()}]});$('modalTitle').tabIndex=-1;$('modalTitle').focus({preventScroll:true});$('modal').querySelector('.card')?.scrollTo?.({top:0});
}
function showHauntingAction(slot){
 const result=session.inspect(slot,pose());if(!result.ok)return toast(result.text);
 showModal(result.title,result.text,{choices:(result.choices||[]).map(choice=>({label:choice.label,action:()=>performHauntingAction(slot,choice.id)}))});
}
function performHauntingAction(slot,choice){
 const inspection=session.inspect(slot,pose()),beforeRevision=session.revision,beforeDread=session.state.dread,result=session.act(slot,choice,pose());
 if(!result.ok){toast(result.text);resume();return;}
 if(result.leave)return transition(streetScene);
 if(result.replay)return loadHouse(houseDescriptor,{fresh:true});
 refreshMarkers();checkpoint();const acted=markerActors.find(a=>a.slot?.id===slot.id);if(acted)acted.model.userData.respondAt=gameTime;if(session.revision!==beforeRevision&&session.state.dread<=beforeDread&&!result.completed)magicRealm?.answer(session.type,slot.approachMeters);
 if(result.phrase){audio.scoreQuiet(5.5);audio.phrase(result.phrase);}else if(result.note!==undefined){audio.scoreQuiet(1.5);audio.note(result.note);}else audio.cue(result.completed?'complete':'find');
 if(result.completed){
  night.record(session,house.manifest.name,house.manifest.id);endingPerformance?.dispose();
  dismissStoryBeat();finishNarration();$('toast').style.display='none';const view=camera.getWorldPosition(new THREE.Vector3()),forward=camera.getWorldDirection(new THREE.Vector3());view.addScaledVector(forward,2.6);view.y-=.85;
  endingPerformance=createEndingTheatre(THREE,session,view.toArray(),{reducedMotion:reduced});endingPerformance.root.rotation.y=Math.atan2(-forward.x,-forward.z);scene.add(endingPerformance.root);needsRender=true;
  showModal(result.title,result.text+'\n\nSeal earned · '+night.data.seals.length+'/8 haunting families. Relic: '+RELICS[session.ending.relic].name+'.',{choices:[{label:'Walk back into the street',action:()=>transition(streetScene)},{label:'Return to the hall · see what your ending changed',action:()=>transition(()=>signatureScene('hall',[0,0,8],0))},{label:'Stay and explore',action:()=>resume()},{label:'Find the elevator to Floor 13',action:findConservatoryLift},{label:'Inspect my relic collection',action:relicCollection}]});$('modal').classList.add('ending-view');
 }else{resume();toast(result.text,4500);if(['read','examine'].includes(choice))showObjectNote(inspection.title,inspection.text);}
}
function showHallSite(site){
 if(mode!=='hall'||hallSociety.near(pose().position)?.id!==site.id)return;
 if(site.id==='concierge')return showModal('Mr. Vale · Keeper of Arrivals',hallSociety.welcome()+'\n\nThe cabinet holds your endings. The calling bells summon the Last Waltz. The curved stairs lead to the elevator.',{choices:[{label:'Read the household guestbook',action:()=>showModal('The household guestbook',hallSociety.ledger())},{label:'Review my relics',action:relicCollection},...(session.floor13Unlocked?[{label:'Find the elevator to Floor 13',action:findConservatoryLift}]:[{label:'Ask about Floor 13',action:()=>showModal('The thirteenth button','Finish this mansion’s haunting to awaken the conservatory. Then climb either curved stair and enter the elevator.')}])]});
 if(site.id==='cabinet'){const text=hallSociety.remember();audio.cue('ghost');return showModal('The Cabinet of Unfinished Evenings',text+'\n\n'+hallSociety.ledger());}
 if(site.id==='dance'){const text=hallSociety.invite();resume();audio.phrase?.([0,1,2,1,0,2]);showObjectNote('The Last Waltz',text);return;}
 return showHallBells();
}
function showHallBells(feedback=''){showModal('The Three Calling Bells',(feedback?feedback+'\n\n':'')+hallSociety.bellClue(),{choices:['Moon','Rose','Thorn'].map((name,i)=>({label:'Ring '+name,action:()=>{if(mode!=='hall'||hallSociety.near(pose().position)?.id!=='bells')return;const result=hallSociety.ring(i);audio.note?.(i);if(result.complete){resume();showObjectNote('The household answers',result.text);audio.phrase?.([0,1,2,1,0,2]);}else showHallBells(result.text);}}))});}
function findConservatoryLift(){if(!house||!session?.floor13Unlocked)return;return transition(async()=>{await signatureScene('hall',[0,5.25,11.4],Math.PI);toast('Floor 13 is awake. Walk into the elevator ahead, then choose 13 · Nocturne Conservatory.',8000);});}
function showHerbarium(){showModal('The Glasshouse Keeper',"“Every ending leaves something growing. Tend what is awake. The sleeping beds will wait.”\n\n"+herbarium.entries.length+'/13 specimens recorded.\n\n'+NOCTURNE_SPECIMENS.map(s=>(herbarium.entries.includes(s.id)?'RECORDED · ':activeGroup?.userData.nocturne?.collection.available(s)?'AWAKE · ':'SLEEPING · ')+s.name).join('\n')+'\nThe eight haunting families awaken their own beds. Five curiosities grow here from your first visit. This collection is optional. Your street seals stay yours.');}
function showGardenAction(specimen){const g=activeGroup?.userData.nocturne;if(!g)return;showModal(specimen.name,g.collection.clue(specimen)+'\n\n'+specimen.lore,{choices:g.collection.choices(specimen).map(c=>({label:c.label,action:()=>performGardenAction(specimen,c.id)}))});}
function performGardenAction(specimen,choice){const g=activeGroup?.userData.nocturne;if(mode!=='floor13'||g?.near(pose().position)?.id!==specimen.id)return;const result=g.collection.act(specimen,choice);if(!result.ok)return;resume();if(result.bloom){audio.magic?.('wildbloom');if(choice==='song')audio.phrase?.([0,1,2]);}villageFeedback={site:'garden:'+specimen.id,text:result.text,until:performance.now()+8500};needsRender=true;updateHUD();}
function showVillagePassport(){showModal('The Crooked Hat · Village Passport',FAIR_SITES.map(s=>(villagePassport.badges.includes(s.id)?'STAMPED · ':'WAITING · ')+s.name).join('\n\n')+'\n\n'+(villagePassport.badges.length===3?'NEIGHBOUR OF THE CROOKED HAT\nThe pot remembers your recipe. Violet saves you a parking space. The pumpkins know your tune.':'Three small wonders. Three stamps. Find the stalls around the clock tower.')+(villagePassport.persisted?'\n\nRemembered on this device.':'\n\nStorage is unavailable; stamps last for this visit.'),{choices:[{label:'Return to the street guide',action:map}]});}
function performNeighborhoodAction(site,choice){if(mode!=='street'||playMode!=='halloween'||dialog||trickRound?.state.status!=='playing'||trickRound.state.pending||street.neighborhood?.near(walker.position)?.id!==site.id)return;const result=street.neighborhood.act(site,choice);if(!result.ok)return;if(result.amount&&trickRound.neighborhoodTreat(site.id))audio.cue('find');toast(result.text,4200);needsRender=true;updateHUD();}
function performWorldChoice(action,choice){return action.neighborhood?performNeighborhoodAction(action.neighborhood,choice):action.botanical?performGardenAction(action.botanical,choice):action.village?performVillageAction(action.village,choice):performHauntingAction(action.slot,choice);}
function showVillageAction(site){showModal(site.name,street.village.game.clue(site.id),{choices:street.village.game.choices(site.id).map(c=>({label:c.label,action:()=>performVillageAction(site,c.id)}))});}
function performVillageAction(site,choice){
 if(mode!=='street'||street.village.near(pose().position)?.id!==site.id)return;
 if(playMode==='halloween'&&(trickRound.state.status!=='playing'||trickRound.state.pending))return;
 const result=street.village.game.act(site.id,choice);if(!result.ok)return;let extra='';
 if(result.note!==undefined)audio.note(result.note);else audio.cue(result.success?'complete':'find');
 if(result.bell)audio.phrase?.([0,1,2]);if(result.recall)street.village.neighbours.route.recall();if(result.guide){const target=FAIR_SITES.find(s=>s.id===result.guide);if(target)magicRealm?.answer('escort',target.approach);}
 if(result.social&&choice==='parade')audio.phrase?.([0,1,2,1]);
 if(result.success){const stamped=villagePassport.stamp(site.id);magicRealm?.answer(site.id==='choir'?'choir':'garden',site.approach);if(playMode==='halloween'&&trickRound.festivalTreat(site.id))extra=' +1 festival sweet!';if(stamped&&villagePassport.badges.length===3)extra+=' Passport complete: Neighbour of the Crooked Hat.';if(!villagePassport.persisted)extra+=' Stamps last for this visit; device storage is unavailable.';}
 resume();villageFeedback={site:site.id,text:result.text+extra,until:performance.now()+7000};needsRender=true;updateHUD();
}
function updateDirectActions(action){
 const tray=$('worldChoices');if(!tray)return;const key=(action?.neighborhood?.id||action?.botanical?.id||action?.village?.id||action?.slot?.id)+':'+(action?.choices||[]).map(c=>c.id).join(',')+':'+dialog+':'+busy;if(tray.dataset.key===key)return;tray.dataset.key=key;tray.replaceChildren();
 if(!(action?.neighborhood||action?.botanical||action?.village||session?.phoenix&&action?.slot)||dialog||busy)return;
 const choices=action.choices||[];if(!choices.length)return;
 for(const [i,choice]of choices.entries()){const b=document.createElement('button');b.textContent=(i+1)+'. '+(action.neighborhood||action.village||action.botanical?choice.label:actionLabel(session,action.slot,choice));b.setAttribute?.('aria-keyshortcuts',String(i+1));b.onclick=()=>performWorldChoice(action,choice.id);tray.append(b);}
}
function updateNightHUD(){
 if(mode==='floor13'&&session?.phoenix)$('mapButton').textContent='Herbarium';else if(!session?.phoenix)$('mapButton').textContent='Map';$('journalButton').hidden=!!session?.phoenix;
 const panel=$('nightPanel');if(!panel)return;panel.hidden=!playing||!session?.phoenix||mode==='street'||mode==='floor13';if(panel.hidden)return;updateLanternGuide();
 const watched=session.type==='vigil'&&session.watch().watching;
 panel.dataset.state=watched?'watching':session.state.stage==='complete'?'complete':'dreaming';
 $('nightRule').textContent=session.definition.subtitle;
 $('nightStatus').textContent=session.type==='vigil'?(watched?'WATCHING · stand still':'DREAMING · move now')+' · '+session.watch().remaining+'s':session.progress();
 const amount=session.type==='heist'?session.state.alarm:session.type==='escort'?100-session.state.light:session.type==='loop'?100*(1-session.state.remaining/(session.state.gentle?240:120)):session.state.dread;
 $('nightGauge').style.width=Math.max(0,Math.min(100,amount))+'%';$('nightMeter').setAttribute?.('aria-valuenow',Math.round(amount));
 $('nightMeter').setAttribute?.('aria-label',session.type==='heist'?'Collector alarm':session.type==='escort'?'Companion light lost':session.type==='loop'?'Time elapsed in this fold':'Dread');
 $('nightBell').hidden=session.state.relic!=='bell'||session.state.bellUsed;
 $('mapButton').textContent='Field journal';
}
function tickHaunting(dt){
 if(!session?.phoenix||!walker?.active)return;
 if(!session.state.encounters['playtest:learned']&&session.state.elapsed===0){updateNightHUD();return;}
 for(const event of session.tick(dt,pose())){if(event.kind!=='phase')audio.effect(event.kind==='success'?'clock':event.kind==='warning'?'draft':'whisper');if(event.kind!=='reveal')toast(event.text,3500);if(event.kind==='reveal'){haunting.event({kind:'reflection',roomId:walker.currentRoomId});presentStoryBeat(event.text);}}
 if(session.revision!==hauntingRevision){hauntingRevision=session.revision;refreshMarkers();checkpoint();}
 if(session.type==='escort'&&session.state.escortStarted&&session.state.escortIndex<3){const c=session.state.companion;if(c?.scene===mode){if(!hauntCompanion){hauntCompanion=createHauntingProp(THREE,{...session.stations[0],label:'Your traveling guest'},session);markers.add(hauntCompanion);}hauntCompanion.position.fromArray(c.position);hauntCompanion.rotation.y=Math.atan2(walker.position[0]-c.position[0],walker.position[2]-c.position[2]);}else if(hauntCompanion)hauntCompanion.visible=false;}
 updateNightHUD();
}
function showObjectNote(title,text){$('storyBeatEyebrow').textContent='FIELD NOTE';$('storyBeatTitle').textContent=title;$('storyBeatText').textContent=text;$('storyBeat').hidden=false;storyBeatUntil=performance.now()+14000;}
function dismissStoryBeat(){storyBeatUntil=0;const panel=$('storyBeat');if(panel)panel.hidden=true;}
function presentStoryBeat(text){if(!session?.phoenix||session.state.encounters['director:reveal'])return;session.state.encounters['director:reveal']=true;finishNarration();checkpoint();$('storyBeatEyebrow').textContent='THE HOUSE TURNS';$('storyBeatTitle').textContent=HOUSE_VOICES[session.type].turn;$('storyBeatText').textContent=text;$('storyBeat').hidden=false;storyBeatUntil=performance.now()+8500;audio.scoreQuiet(.8);}
$('dismissStoryBeat').onclick=dismissStoryBeat;
function toggleLanternGuide(){night.setGuide(!night.data.guide);if(session&&markers){refreshMarkers();updateNightHUD();}}
$('guideButton').onclick=toggleLanternGuide;
function updateLanternGuide(){const guide=lanternGuide(session,pose());$('guideButton').textContent=night.data.guide?'Lantern guide: on':'Lantern guide: off';$('nightNext').hidden=!night.data.guide; if(guide)$('nightNext').textContent=guide.instruction+'\n'+guide.location;for(const actor of markerActors)if(actor.model.userData.guideRing)actor.model.userData.guideRing.visible=!!(night.data.guide&&guide?.sameRoom&&guide.targetId===actor.slot.id);}
function scareSettings(){const describe={gentle:'Atmospheric sounds and false alarms. No sudden figures.',spooky:'Occasional figures, long quiet intervals, and plenty of false alarms.',intense:'More frequent surprises, with time to recover between them.'};showModal('How haunted?',describe[scareOptions.level]+(reduced?'\n\nReduced motion is active: sudden figures stay disabled.':'')+'\n\nScares never damage you, take over the camera, or block an exit. Changes apply immediately.',{choices:[...['gentle','spooky','intense'].map(level=>({label:(scareOptions.level===level?'Selected: ':'')+level[0].toUpperCase()+level.slice(1),action:()=>{scareOptions.level=level;saveScareOptions();scareSettings();}})),{label:scareOptions.sound?'Turn off scare sounds':'Turn on scare sounds',action:()=>{scareOptions.sound=!scareOptions.sound;saveScareOptions();scareSettings();}},{label:'Back to the field journal',action:hauntingJournal}]});}
function saveScareOptions(){haunting?.cancelScares();try{localStorage.setItem('bh-scares:v1',JSON.stringify(scareOptions));}catch{toast('Scare settings will last for this session.');}}
function readRoomMemory(content){session.state.encounters['memory:'+content.discovery.id]=true;checkpoint();resume();haunting.event({kind:content.reaction.kind,roomId:content.roomId});audio.effect(content.reaction.kind);showObjectNote(content.story.title,content.story.text);}
function hauntingJournal(){
 const s=session?.phoenix?session:null,entries=night.data.history.slice(-8).reverse(),text=(s?s.definition.rule+'\n\n'+s.progress()+'\n'+s.hint()+'\n\nFIELD NOTES\n'+s.state.journal.map(t=>'• '+t).join('\n\n')+'\n\n':'')+'THE STREET REMEMBERS\n'+(entries.length?entries.map(h=>h.house+' — '+h.ending).join('\n'):'No endings written yet. Every door is an invitation.')+'\n\n'+streetLedger(night)+'\n\nCARRIED RELIC: '+(RELICS[night.data.equipped]?.name||'None')+'\n'+(RELICS[night.data.equipped]?.description||'Choose a relic after your first ending.')+'\n\n'+(night.data.gentle?'Gentle night: longer loops and softer pressure.':'Standard night: the house keeps its usual pace.');
 const choices=[{label:session?.floor13Unlocked?'Floor 13 · visit the conservatory':'Floor 13 · how to unlock it',action:session?.floor13Unlocked?findConservatoryLift:()=>showModal('The thirteenth button','Finish this mansion’s haunting to awaken Floor 13. Then enter the elevator in the Grand Main Hall and choose 13. The conservatory is an optional botanical collection; it never blocks the street finale.')},{label:'Open the living grimoire · '+grimoire.marks.length+'/8 witch marks',action:spellbook},{label:'Open my relic collection · '+night.data.relics.length+'/4',action:relicCollection},{label:'Scares: '+scareOptions.level+' · '+(scareOptions.sound?'sound on':'sound off'),action:scareSettings},{label:night.data.guide?'Turn off the lantern guide':'Turn on the lantern guide',action:()=>{toggleLanternGuide();hauntingJournal();}},...night.data.relics.map(id=>({label:(night.data.equipped===id?'Equipped: ':'Carry next house: ')+RELICS[id].name,action:()=>{night.equip(id);hauntingJournal();}})),{label:night.data.gentle?'Use standard pace in future houses':'Use gentle pace in future houses',action:()=>{night.setGentle(!night.data.gentle);hauntingJournal();}}];
 if(s){const memory=mode==='house'?haunting.roomContents.find(c=>c.roomId===currentRoom.id&&c.discovery):null;if(memory)choices.unshift({label:'Read this room’s memory · '+memory.story.title,action:()=>readRoomMemory(memory)});try{if(readSave(true))choices.push({label:'Resume the original investigation saved here',action:()=>loadHouse(houseDescriptor,{classic:true})});}catch{}choices.unshift({label:'Sketch the discovered rooms',action:()=>{showModal('Your discoveries','Haunting objects are named on their plaques. Floors and corridors keep the architect’s layout.',{map:true,choices:house.manifest.floors.map((f,i)=>({label:f.name||'Floor '+(i+1),action:()=>{showModal(f.name||'Floor '+(i+1),'Your explored rooms.',{map:true});drawMap(i);}}))});drawMap(Math.max(0,currentRoom?.floor||0));}});if(s.state.relic==='bell'&&!s.state.bellUsed)choices.unshift({label:'Ring the mercy bell · once this house',action:()=>{s.useBell();checkpoint();resume();}});}
 showModal('The field journal',text,{choices});
}
function castSpell(){
 if(!playing||dialog||busy||!walker?.active||!magicRealm)return;
 const result=magicRealm.cast(grimoire.data.equipped,walker.position,walker.yaw);
 if(result.ok){haunting?.cancelScares();audio.magic?.(grimoire.data.equipped);needsRender=true;}toast(result.text,result.revealed?6500:3500);
}
function spellbook(){
 const owned=grimoire.marks;showModal('The living grimoire','Choose a spell, then press F or tap its button to cast. Your puzzle supplies stay yours.\n\n'+(owned.length===8?'THE MOON GARDEN IS AWAKE · All eight flowers are yours.':owned.length+'/8 witch marks discovered. Witchlight wakes hidden marks; touch them to keep their pages.'),{choices:[...Object.entries(SPELLS).map(([id,spell])=>({label:(grimoire.data.equipped===id?'Prepared: ':'Prepare ')+spell.name,action:()=>{grimoire.equip(id);if(playing){resume();castSpell();}else spellbook();}}))]});
 const book=document.createElement('div');book.id='magicBook';book.className='magic-book';
 for(const [id,spell]of Object.entries(SPELLS)){const card=document.createElement('article');card.className='spell-page';card.dataset.spell=id;const title=document.createElement('h3');title.textContent=spell.name;const line=document.createElement('p');line.textContent=spell.line;const how=document.createElement('small');how.textContent=spell.instruction;card.append(title,line,how);book.append(card);}
 const marks=document.createElement('div');marks.className='witch-mark-grid';for(const [i,mark]of WITCH_MARKS.entries()){const page=document.createElement('div');page.className='witch-mark';page.dataset.known=String(owned.includes(i));const title=document.createElement('strong');title.textContent=owned.includes(i)?mark.name:'Unwritten page';const line=document.createElement('span');line.textContent=owned.includes(i)?mark.line:'Witchlight may find this story.';page.append(title,line);marks.append(page);}book.append(marks);$('choices').after(book);
}
$('magicButton').onclick=castSpell;$('spellbookButton').onclick=spellbook;$('landingMagic').onclick=spellbook;
function relicCollection(){
 showModal('Your relic cabinet',night.data.relics.length+'/4 relics collected · '+night.data.seals.length+'/8 seals. Carry one relic into your NEXT house. The current haunting keeps the relic it began with.',{choices:[{label:'Back to the field journal',action:hauntingJournal}]});
 const grid=document.createElement('div');grid.className='relic-grid';grid.id='relicCabinet';
 for(const [id,relic]of Object.entries(RELICS)){const owned=night.data.relics.includes(id),card=document.createElement('button');card.className='relic-card';card.disabled=!owned;card.setAttribute('aria-pressed',String(night.data.equipped===id));const icon=document.createElement('span');icon.className='relic-icon';icon.textContent=owned?RELIC_SYMBOLS[id]:'?';icon.setAttribute('aria-hidden','true');const title=document.createElement('strong');title.textContent=relic.name;const detail=document.createElement('span');detail.textContent=owned?relic.description:'Finish more hauntings to discover this relic.';const status=document.createElement('small');status.textContent=!owned?'UNDISCOVERED':night.data.equipped===id?'PACKED FOR NEXT HOUSE':'Tap to pack for your next house';card.append(icon,title,detail,status);card.onclick=()=>{night.equip(id);relicCollection();};grid.append(card);}
 $('modalText').after(grid);controllerMenuIndex=0;modalButtons()[0]?.focus();
}
$('journalButton').onclick=hauntingJournal;$('landingJournal').onclick=hauntingJournal;
$('nightBell').onclick=()=>{if(session?.phoenix&&session.useBell()){checkpoint();updateNightHUD();}};

function houseVersionText(h){return (h.local?'Local test copy':'Published mansion')+' · '+(h.geometryLevel||'Legacy CASA')+' · '+(h.fingerprint?.slice(0,12)||'version unavailable');}
function renderHouseLibrary(){const target=$('houseLibrary');if(!target)return;target.replaceChildren();for(const h of catalog.list()){const row=document.createElement('p'),label=document.createElement('span');label.textContent=h.name+' — '+houseVersionText(h)+(h.local&&h.publishedVersion?' (overrides the published mansion on this browser)':'');row.append(label);if(h.local){const button=document.createElement('button');button.textContent=h.publishedVersion?'Use published version':'Remove local copy';button.onclick=()=>removeLocalHouse(h);row.append(button);}target.append(row);}}
async function removeLocalHouse(h){try{await catalog.removeLocal(h.id);renderHouseLibrary();if(playing){closeModal(false);await transition(streetScene);}toast(h.publishedVersion?'Published version restored.':'Local copy removed.');}catch(e){toast(e.message);}}
function houseVersions(){showModal('House versions',catalog.list().map(h=>h.name+' — '+houseVersionText(h)).join('\n\n'),{choices:catalog.list().filter(h=>h.local).map(h=>({label:(h.publishedVersion?'Use published version: ':'Remove local copy: ')+h.name,action:()=>removeLocalHouse(h)}))});}
$('houseVersionsButton').onclick=houseVersions;
$('startStreet').onclick=async()=>{try{$('startStreet').disabled=true;await initialize3D();$('landing').hidden=true;document.body.classList.add('playing');playing=true;audio.start();if(playMode==='halloween')trickRound=createTrickOrTreat();trickClock=0;await transition(streetScene);}catch(e){$('loadStatus').textContent='3D could not start: '+e.message+'\nThe game needs WebGL. Try a browser with WebGL enabled, then reload the game.';atmosphere?.dispose();document.getElementById('bh-walk-panel')?.remove();renderer?.dispose();renderer=null;$('startStreet').disabled=false;}};
$('houseFiles').onchange=async()=>{if(localImportRunning)return;const files=[...$('houseFiles').files];if(!files.length)return;localImportRunning=true;$('houseFiles').disabled=true;$('addHousesButton').disabled=true;try{const batch=await importCasaBatch(files,{catalog,onProgress:p=>{$('loadStatus').textContent=p.phase+' · '+p.file.name;if(playing)toast($('loadStatus').textContent,15000);}});renderHouseLibrary();if(playing&&mode==='street')await transition(streetScene);const details=batch.results.filter(r=>!r.ok).map(r=>r.file.name+': '+r.error).join('\n');$('loadStatus').textContent=batch.message+(details?'\n'+details:'');if(playing){if(batch.failed)showModal('House import results',batch.message+'\n\n'+details);else toast(batch.message,7000);}}finally{localImportRunning=false;$('houseFiles').disabled=false;$('addHousesButton').disabled=false;$('houseFiles').value='';}};
$('hintButton').onclick=()=>{if(mode==='floor13'&&session?.phoenix)return showHerbarium();if(session?.phoenix)return showModal('A thread through the dark',session.hint(),{choices:[{label:'Open the field journal',action:hauntingJournal}]});if(!session){const near=nearestAction();if(near?.village)return showVillageAction(near.village);return map();}const slot=session.activeSlots()[0];if(!slot)return toast(session.objective());const room=house.rooms.find(r=>r.id===slot.roomId);toast(session.objective()+' '+(room?'Look in '+room.name+' on '+house.manifest.floors[room.floor].name+'.':''),7000);};$('addHousesButton').onclick=()=>$('houseFiles').click();
$('interact').onclick=interact;$('mapButton').onclick=map;$('soundButton').onclick=()=>{$('soundButton').textContent=audio.toggle()?'Sound on':'Sound off';};$('voiceButton').onclick=()=>{voices=!voices;$('voiceButton').textContent=voices?'Voices on':'Voices off';if(!voices)window.speechSynthesis?.cancel();};$('pauseButton').onclick=()=>{if(midwayRide)return midwayRide.togglePause();if(playMode==='midway')return showModal('A Midway intermission','The carriages will wait. Continue when you are ready.',{choices:[{label:'Game modes',action:modeMenu}]});if(playMode==='halloween')return showModal('A Halloween breather','The timer is paused. Continue when you are ready.',{choices:[{label:'Game modes / restart',action:modeMenu}]});checkpoint();showModal('A quiet moment','Your progress is saved on this device.',{choices:house?[{label:'Walk the house cemetery',action:()=>transition(groundsScene)},{label:session?.phoenix?'Awaken a different haunting':'Begin The Unwritten Night in this house',action:()=>loadHouse(houseDescriptor,{fresh:true})}]:[]});};$('streetButton').onclick=()=>playMode==='halloween'?modeMenu():transition(streetScene);
window.addEventListener('keydown',e=>{if(midwayRide){if(e.target.matches?.('input,select,textarea')||e.isComposing)return;if(e.code==='Space'&&e.target.closest?.('button,a,summary'))return;if(!e.repeat&&['KeyE','Space','Escape','KeyM'].includes(e.code)){e.preventDefault();if(e.code==='Escape')midwayRide.togglePause();else if(e.code==='KeyM')midwayRide.showGuide();else midwayRide.action();}return;}if(dialog&&e.code==='Tab'){const buttons=modalButtons();const index=buttons.indexOf(document.activeElement),next=e.shiftKey?(index<=0?buttons.length-1:index-1):(index+1)%buttons.length;e.preventDefault();buttons[next]?.focus();return;}if(e.target.matches?.('input,select,textarea')||e.isComposing)return;if(e.code==='Enter'&&!e.repeat&&!dialog&&!e.target.closest?.('button,a,summary')&&nearestAction()?.confirmation){e.preventDefault();interact();return;}if(e.code==='KeyN'&&!e.repeat&&declineEntry()){e.preventDefault();return;}if(!dialog&&!e.repeat&&['Digit1','Digit2','Digit3'].includes(e.code)){const near=nearestAction(),choice=near?.choices?.[Number(e.code.at(-1))-1];if(choice){e.preventDefault();performWorldChoice(near,choice.id);return;}}if(e.code==='KeyE'&&!e.repeat){e.preventDefault();interact();}if(e.code==='KeyF'&&!e.repeat&&!dialog&&playing){e.preventDefault();castSpell();}if(e.code==='KeyM'&&!dialog&&playing){e.preventDefault();map();}if(e.code==='Escape'&&playing){e.preventDefault();if(dialog)$('closeModal').click();else $('pauseButton').click();}});
window.addEventListener('pagehide',()=>{checkpoint();audio.setHidden(true);});window.addEventListener('pageshow',()=>{audio.setHidden(document.hidden);lastFrame=performance.now();trickClock=0;});document.addEventListener('visibilitychange',()=>{lastFrame=performance.now();trickClock=0;audio.setHidden(document.hidden);if(document.hidden&&playing&&!dialog){checkpoint();showModal('Paused','The house will wait for you.');}});window.addEventListener('resize',()=>{if(!renderer)return;renderer.setPixelRatio(drawingPixelRatio(innerWidth,innerHeight,devicePixelRatio)*(softwareGPU?.55:1));renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();needsRender=true;});
try{const houses=await catalog.init();renderHouseLibrary();$('startStreet').disabled=false;$('startStreet').textContent=playMode==='halloween'?'Start Trick or Treat · 10 minutes':playMode==='midway'?'Enter the Haunted Midway':'Enter Black Hollow';$('loadStatus').textContent='The gates are ready.';}catch(e){$('loadStatus').textContent=e.message;$('startStreet').textContent='Street unavailable';}

let controllerMenuIndex=-1;
const gamepad=createGamepadInput({getPads:()=>{if(!navigator.getGamepads)throw Error('Gamepad API unavailable');return navigator.getGamepads();},onMove:value=>walker?.setGamepadState(value),onStatus:text=>{$('controllerStatus').textContent=text;},onCapture:action=>{toast(action+' mapped.');controllerSettings();},onAction:action=>{
 if(document.hidden||busy)return;
 if(midwayRide){if(action==='interact')midwayRide.action();else if(['pause','back'].includes(action))midwayRide.togglePause();else if(action==='map')midwayRide.showGuide();return;}
 if(dialog){const buttons=modalButtons();if(['forward','left','backward','right'].includes(action)){const direction=['forward','left'].includes(action)?-1:1;controllerMenuIndex=(controllerMenuIndex+direction+buttons.length)%buttons.length;buttons[controllerMenuIndex].focus();}else if(action==='interact'){(buttons[controllerMenuIndex]||$('closeModal')).click();}else if(action==='back'||action==='pause')$('closeModal').click();return;}
 if(!playing){if(action==='interact'&&!$('startStreet').disabled)$('startStreet').click();return;}
 if(action==='interact'){const near=nearestAction();if(near?.choices?.length>1)(near.botanical?showGardenAction(near.botanical):near.village?showVillageAction(near.village):showHauntingAction(near.slot));else interact();}else if(action==='back'){if(!declineEntry())$('pauseButton').click();}else if(action==='pause')$('pauseButton').click();else if(action==='map')map();else if(action==='camera')walker?.setCameraMode(({cinematic:'explorer',explorer:'first',first:'cinematic'})[walker.cameraMode]);
}});
function controllerSettings(){showModal('Optional controller',gamepad.status+'\n\nD-pad / left stick: walk and turn. Face button: interact / confirm. Back: close. Start: pause. Camera and map have optional bindings.\n\nGeneric Nintendo-style USB controllers may need remapping. Choose an action below, release the controls, then press the desired button or direction. Keyboard and touch remain available.',{choices:[{label:gamepad.enabled?'Disable controller':'Enable controller',action:()=>{gamepad.setEnabled(!gamepad.enabled);controllerSettings();}},...controllerActions.map(action=>({label:'Remap '+action,action:()=>{showModal('Map '+action,'Release the controls, then press the button or direction for '+action+'.');if(!gamepad.remap(action))toast('Press a button on your connected controller first.');}})),{label:'Reset default layout',action:()=>{gamepad.resetMapping();controllerSettings();}}]});}
$('controllerButton').onclick=controllerSettings;$('landingControllerButton').onclick=controllerSettings;
function controllerFrame(time){gamepad.poll(time,{focused:!document.hidden&&(document.hasFocus?.()??true),menu:dialog});requestAnimationFrame(controllerFrame);}requestAnimationFrame(controllerFrame);
window.addEventListener('blur',()=>{gamepad.release();if(midwayRide){midwayRide.pause();return;}if(playing&&!dialog&&!busy){checkpoint();showModal('Paused','The house will wait for you. Continue when you are ready.');}});

function chooseLandingMode(value){playMode=value;$('modeChoice').value=value;$('storyChoice').setAttribute?.('aria-pressed',String(value==='story'));$('halloweenChoice').setAttribute?.('aria-pressed',String(value==='halloween'));$('midwayChoice').setAttribute?.('aria-pressed',String(value==='midway'));$('startStreet').textContent=value==='halloween'?'Start Trick or Treat':value==='midway'?'Enter the Haunted Midway':'Enter Black Hollow';$('modeDescription').textContent=value==='midway'?'Board a phantom carriage through each mansion. Haunted elevators carry you between floors.':value==='halloween'?'Collect candy for ten minutes. Watch for tricks, meet the neighbours, and pause whenever you like.':'Explore at your own pace. Each mansion has its own mystery.';}
$('midwayChoice').onclick=()=>chooseLandingMode('midway');$('storyChoice').onclick=()=>chooseLandingMode('story');$('halloweenChoice').onclick=()=>chooseLandingMode('halloween');
function optionsMenu(){showModal('Your visit to Black Hollow','Adjust your controls, sound, or style of play. The game is paused.',{choices:[{label:'How to play',action:()=>showModal('A little guidance','Walk up to a mansion porch and choose Yes to enter. Nearby objects offer buttons for what you can do. Follow the house objective, read its clues, and choose an ending.\n\nTrick or Treat stays outside: visit doorsteps for candy, step away before revisiting, and watch the ten-minute clock.\n\nUse Hint for help. Your prepared spell adds a little magic; the Spellbook explains the three spells.')},{label:'Controls & controller',action:controllerSettings},{label:'Journal, pacing & scare settings',action:hauntingJournal},{label:$('soundButton').textContent+' · toggle',action:()=>{$('soundButton').click();optionsMenu();}},{label:$('voiceButton').textContent+' · toggle',action:()=>{$('voiceButton').click();optionsMenu();}},{label:'Change game mode / restart',action:modeMenu},...(mode!=='street'?[{label:'Return to the town',action:()=>transition(streetScene)}]:[])]});}
$('optionsButton').onclick=optionsMenu;
$('modeChoice').onchange=()=>chooseLandingMode($('modeChoice').value);
$('modeButton').onclick=modeMenu;
function modeMenu(){showModal('Choose your night','Choose house mysteries, a candy hunt, or phantom-carriage attractions.',{choices:[{label:'Start Trick or Treat · 10 minutes',action:()=>changePlayMode('halloween')},{label:'Explore haunted houses',action:()=>changePlayMode('story')},{label:'The Haunted Midway · phantom carriage rides',action:()=>changePlayMode('midway')}]});}
async function changePlayMode(value){playMode=value;trickRound=value==='halloween'?createTrickOrTreat():null;trickClock=0;await transition(streetScene);}
function finishTrickRound(){halloween?.settle();const s=trickRound.state;showModal('The Halloween bell rings',countLabel(s.candy,'candy','candies')+' in your bucket!\n'+countLabel(s.treats,'treat')+' · '+countLabel(s.tricks,'trick')+' · '+countLabel(s.visits,'doorstep visit')+'\n'+countLabel(s.festivalSweets,'festival sweet')+'\n'+countLabel(s.neighborhoodSweets,'honesty-bowl sweet')+' · '+(street.neighborhood?.life.state.stamps.length||0)+' bat stamps\nBest treat streak: '+s.bestStreak,{choices:[{label:'Another ten-minute round',action:()=>changePlayMode('halloween')},{label:'Explore haunted houses',action:()=>changePlayMode('story')}]});audio.cue('complete');}
function updateTrickOrTreat(seconds,dt){if(!trickRound||!halloween)return;const event=trickRound.advance(seconds);if(event?.type==='finished'){finishTrickRound();return;}if(event){halloween.settle();audio.cue(event.type==='trick'?'ghost':'find');toast(event.type==='trick'?'TRICK! '+Math.abs(event.change)+' candies vanish.':'TREAT! +'+event.change+' '+(event.change===1?'candy':'candies')+' in your bucket.',2600);}trickRound.rearm(street.lots,walker.position);if(!event&&trickRound.state.status==='playing'&&!trickRound.state.pending){const lot=street.lots.find(l=>l.entryReady&&street.neighborhood?.isOpen(l.house.id)!==false&&distance(walker.position,l.door)<1.05&&trickRound.canVisit(l.house.id));if(lot){const profile=street.neighborhood?.profile(lot.house.id),visit=trickRound.visit(lot.house.id,{amount:profile?.amount||1});halloween.begin(lot.house.id,visit.trick);if(voices)audio.greeting();audio.doors();toast(profile?.kind==='joker'?profile.joke:'Trick or treat! · '+lot.house.name,profile?.kind==='joker'?4400:2400);}}street.neighborhood?.setRound(trickRound.state);halloween.tick(gameTime,dt,walker.position,walker.yaw,trickRound.state);}
